(22,'alarm_todo_normal','TODO Alarm - Běžná připomínka','','Dobrý den,\n\npřipomínáme Vám úkol:\n\n',1,'Připomínka úkolu: {todo_title}','Připomínka úkolu: \"{todo_title}\". Termín: {todo_deadline}, Alarm: {alarm_time}.','normal',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(23,'alarm_todo_high','TODO Alarm - URGENTNÍ','⚠️ URGENTNÍ: Úkol {todo_title} vyžaduje pozornost!','Dobrý den,\n\n⚠️ URGENTNÍ ÚKOL vyžaduje Vaši pozornost:\n\n',1,'⚠️ URGENTNÍ: {todo_title}','⚠️ URGENTNÍ úkol: \"{todo_title}\". Termín: {todo_deadline}. Vyžaduje okamžitou pozornost!','urgent',1,'2025-10-29 20:46:18',NULL),
(24,'alarm_todo_expired','TODO Alarm - Prošlý termín','❌ Prošel termín úkolu: {todo_title}','Dobrý den,\n\n❌ Prošel termín následujícího úkolu:\n\n',1,'❌ Prošlý termín: {todo_title}','❌ Úkol \"{todo_title}\" má prošlý termín ({todo_deadline}). Uplynulo: {days_overdue} dní.','high',1,'2025-10-29 20:46:18',NULL),
