(33,'system_security_alert','Bezpečnostní upozornění','','Dobrý den,\n\n',1,'BEZPEČNOSTNÍ ALERT: {alert_type}','Detekováno: {alert_type}. Čas: {detection_time}. Akce: {recommended_action}','urgent',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(34,'system_user_login_alert','Neobvyklé přihlášení detekováno','⚠️ Neobvyklé přihlášení do Vašeho účtu','Dobrý den,\n\n⚠️ Detekovali jsme neobvyklé přihlášení do Vašeho účtu:\n\n',1,'⚠️ Neobvyklé přihlášení','Přihlášení z {location} ({country}) v {login_time}. IP: {ip_address}. Zkontrolujte, zda jste to byli Vy.','high',1,'2025-10-29 20:46:18',NULL),
(35,'system_session_expired','Relace vypršela','Vaše relace v systému vypršela','Dobrý den,\n\nVaše přihlášení do systému vypršelo z důvodu neaktivity.\n\n⏰ Délka neaktivity: {inactive_duration} minut\n\n',0,'Vaše relace vypršela','Vaše relace vypršela z důvodu neaktivity. Přihlaste se prosím znovu.','normal',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(36,'system_storage_warning','Upozornění na nedostatek místa','⚠️ Nedostatek místa na disku - {usage_percent}%','Dobrý den,\n\n⚠️ Úložný prostor serveru je téměř plný:\n\n',1,'⚠️ Nedostatek místa','Disk zaplněn na {usage_percent}%. Zbývá {free_space} GB. Doporučujeme archivaci.','high',1,'2025-10-29 20:46:18',NULL),
(37,'user_mention','Zmínka v komentáři','','Dobrý den,\n\nuživatel {mention_author} vás zmínil v komentáři:\n\n',0,'Byl(a) jste zmíněn(a) uživatelem {mention_author}','{mention_author} vás zmínil v komentáři k objednávce {order_number}.','low',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(38,'deadline_reminder','Upozornění na blížící se termín','⏰ Blíží se termín objednávky {order_number}','Dobrý den,\n\nblíží se termín dodání objednávky:\n\n',1,'⏰ Blíží se termín','Objednávka {order_number} má termín dodání {deadline_date}. Zbývá {days_remaining} dní.','high',1,'2025-10-29 20:46:18',NULL),
(39,'order_unlock_forced','Objednávka násilně odemknuta','','Dobrý den,\n\nobjednávka, kterou jste měli zamčenou, byla násilně odemknuta:\n\n',1,'Násilně odemknuta: {order_number}','Objednávka {order_number} byla násilně odemknuta uživatelem {unlocked_by}. Důvod: {unlock_reason}','high',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(40,'order_approved','Objednávka schválena (DEPRECATED)','Objednávka {order_number} schválena','DEPRECATED: Použijte order_status_schvalena',0,'Objednávka schválena','DEPRECATED','normal',0,'2025-10-29 20:46:18',NULL),
(41,'order_rejected','Objednávka zamítnuta (DEPRECATED)','Objednávka {order_number} zamítnuta','DEPRECATED: Použijte order_status_zamitnuta',0,'Objednávka zamítnuta','DEPRECATED','normal',0,'2025-10-29 20:46:18',NULL),
