(59,'order_status_realizovana','Objednávka realizována','Objednávka č. {order_number} realizována','Dobrý den,\n\nobjednávka byla úspěšně realizována:\n\nČíslo objednávky: {order_number}\nPředmět: {order_subject}\nDatum realizace: {delivery_date}\n\nZboží bylo dodáno a je připraveno k převzetí / použití.\n\nDetail objednávky najdete v aplikaci Evidence smluv.\n\nS pozdravem,\nSystém Evidence smluv',1,'Objednávka realizována','Objednávka č. {order_number} byla realizována - zboží bylo dodáno','normal',1,'2025-11-02 00:27:53','2025-11-02 00:27:53'),
(60,'order_status_faktura_prirazena','Faktura přiřazena k objednávce','Faktura {invoice_number} přiřazena k objednávce č. {order_number}','Dobrý den,\n\nk objednávce byla přiřazena faktura:\n\nObjednávka: {order_number}\nFaktura: {invoice_number}\nČástka: {invoice_amount} Kč\nDatum vystavení: {invoice_issue_date}\nDatum splatnosti: {invoice_due_date}\n\nDetail faktury najdete v aplikaci Evidence smluv.\n\nS pozdravem,\nSystém Evidence smluv',1,'Faktura přiřazena','K objednávce č. {order_number} byla přiřazena faktura {invoice_number} ve výši {invoice_amount} Kč','normal',1,'2025-11-02 00:27:53','2025-11-02 00:27:53'),
(74,'order_status_faktura_zaplacena','Faktura zaplacena','Faktura {invoice_number} zaplacena','Dobrý den,\n\nfaktura byla uhrazena:\n\nObjednávka: {order_number}\nFaktura: {invoice_number}\nČástka: {invoice_amount} Kč\nDatum úhrady: {payment_date}\n\nDetail platby najdete v aplikaci Evidence smluv.\n\nS pozdravem,\nSystém Evidence smluv',1,'Faktura zaplacena','Faktura {invoice_number} k objednávce č. {order_number} byla zaplacena','normal',1,'2025-11-02 00:28:31','2025-11-02 00:28:31'),
(75,'order_vecna_spravnost_zamitnuta','Věcná správnost zamítnuta - reklamace','❗ Potvrďte věcnou správnost objednávky {order_number}','\n<!-- OUTLOOK COMPATIBLE VERSION - Fixed gradients, box-shadow -->\n<!DOCTYPE html>\n<html lang=\"cs\" xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:o=\"urn:schemas-microsoft-com:office:office\">\n<head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Nová objednávka ke schválení</title>\n    <!--[if mso]>\n    <xml>\n        <o:OfficeDocumentSettings>\n            <o:AllowPNG/>\n            <o:PixelsPerInch>96</o:PixelsPerInch>\n        </o:OfficeDocumentSettings>\n    </xml>\n    <style type=\"text/css\">\n        body, table, td, p, a {font-family: Arial, sans-serif !important;}\n        table {border-collapse: collapse !important;}\n    </style>\n    <![endif]-->\n</head>\n<body style=\"margin: 0; padding: 0; font-family: Arial, sans-serif; background-color: #f5f5f5;\">\n    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse; background-color: #f5f5f5;\">\n        <tr>\n            <td align=\"center\" style=\"padding: 40px 20px;\">\n                <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" style=\"width: 600px; max-width: 600px; border-collapse: collapse; background-color: #ffffff; border: 1px solid #bfdbfe;\">\n                    <!-- Header - Orange theme -->\n                    <tr>\n                        <td align=\"center\" style=\"background-color: #3b82f6; padding: 0; border-bottom: 4px solid #2563eb;\">\n                            <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse;\">\n                                <tr>\n                                    <td align=\"center\" style=\"padding: 30px 20px;\">\n                                        <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse;\">\n                                            <tr>\n                                                <td align=\"center\" style=\"padding: 0;\">\n                                                    <h1 style=\"margin: 0; padding: 0; color: #ffffff; font-size: 24px; font-weight: 700; font-family: Arial, sans-serif; line-height: 1.2;\">Potvrďte věcnou správnost</h1>\n                                                </td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                    \n                    <!-- Content -->\n                    <tr>\n                        <td style=\"padding: 40px 30px;\">\n                            <p style=\"margin: 0 0 20px 0; font-size: 16px; line-height: 1.6; color: #374151; font-family: Arial, sans-serif;\">\n                                Dobrý den <strong style=\"font-weight: 700;\">{recipient_name}</strong>,\n                            </p>\n                            \n                            <p style=\"margin: 0 0 30px 0; font-size: 16px; line-height: 1.6; color: #374151; font-family: Arial, sans-serif;\">k objednávce byla přiložena faktura. Prosím <strong style=\"font-weight: 700;\">zkontrolujte věcnou správnost dodávky</strong> - dodané zboží, množství, kvalitu a soulad s fakturou.</p>\n                            \n                            <!-- Order Details Card -->\n                            <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse; background-color: #eff6ff; border: 2px solid #bfdbfe; margin-bottom: 30px;\">\n                                <tr>\n                                    <td style=\"padding: 20px;\">\n                                        <h2 style=\"margin: 0 0 15px 0; color: #1f2937; font-size: 18px; font-weight: 600; font-family: Arial, sans-serif;\">\n                                            &#128203; Detaily objednávky\n                                        </h2>\n                                        \n                                        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse;\">\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif; width: 40%;\">Číslo objednávky:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 14px; font-family: Arial, sans-serif;\">{order_number}</td>\n                                            </tr>\n                                            <tr>\n                                                <td colspan=\"2\" style=\"border-bottom: 1px solid #bfdbfe; padding: 0; line-height: 1px;\">&nbsp;</td>\n                                            </tr>\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif;\">Předmět:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 14px; font-family: Arial, sans-serif;\">{predmet}</td>\n                                            </tr>\n                                            <tr>\n                                                <td colspan=\"2\" style=\"border-bottom: 1px solid #bfdbfe; padding: 0; line-height: 1px;\">&nbsp;</td>\n                                            </tr>\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif;\">Střediska:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 14px; font-family: Arial, sans-serif;\">{strediska}</td>\n                                            </tr>\n                                            <tr>\n                                                <td colspan=\"2\" style=\"border-bottom: 1px solid #bfdbfe; padding: 0; line-height: 1px;\">&nbsp;</td>\n                                            </tr>\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif;\">Zdroj financování:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 14px; font-family: Arial, sans-serif;\">{financovani}</td>\n                                            </tr>\n                                            <tr>\n                                                <td colspan=\"2\" style=\"border-bottom: 1px solid #bfdbfe; padding: 0; line-height: 1px;\">&nbsp;</td>\n                                            </tr>\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif;\">Poznámka:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 14px; font-family: Arial, sans-serif;\">{financovani_poznamka}</td>\n                                            </tr>\n                                            <tr>\n                                                <td colspan=\"2\" style=\"border-bottom: 1px solid #bfdbfe; padding: 0; line-height: 1px;\">&nbsp;</td>\n                                            </tr>\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif;\">Cena s DPH:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 16px; font-weight: 700; font-family: Arial, sans-serif;\">{amount}</td>\n                                            </tr>\n                                            <tr>\n                                                <td colspan=\"2\" style=\"border-bottom: 1px solid #bfdbfe; padding: 0; line-height: 1px;\">&nbsp;</td>\n                                            </tr>\n                                            <tr>\n                                                <td style=\"padding: 8px 0; font-weight: 600; color: #4b5563; font-size: 14px; font-family: Arial, sans-serif;\">Datum vytvoření:</td>\n                                                <td style=\"padding: 8px 0; color: #1f2937; font-size: 14px; font-family: Arial, sans-serif;\">{date}</td>\n                                            </tr>\n                                        </table>\n                                    </td>\n                                </tr>\n                            </table>\n                            \n                            <!-- CTA Button -->\n                            <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse; margin: 30px 0;\">\n                                <tr>\n                                    <td align=\"center\">\n                                        <!--[if mso]>\n                                        <v:roundrect xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:w=\"urn:schemas-microsoft-com:office:word\" \n                                            href=\"https://erdms.zachranka.cz/eeo-v2/order-form-25?edit={order_id}\" \n                                            style=\"height:48px;v-text-anchor:middle;width:320px;\" \n                                            arcsize=\"10%\" \n                                            stroke=\"f\" \n                                            fillcolor=\"#3b82f6\">\n                                            <w:anchorlock/>\n                                            <center style=\"color:#ffffff;font-family:Arial, sans-serif;font-size:16px;font-weight:bold;\">\n                                                Potvrdit věcnou správnost\n                                            </center>\n                                        </v:roundrect>\n                                        <![endif]-->\n                                        <!--[if !mso]><!-->\n                                        <a href=\"https://erdms.zachranka.cz/eeo-v2/order-form-25?edit={order_id}\" \n                                           target=\"_blank\" \n                                           style=\"display: inline-block; background-color: #3b82f6; color: #ffffff; text-decoration: none; padding: 14px 32px; font-size: 16px; font-weight: 600; font-family: Arial, sans-serif; border: 2px solid #2563eb; text-align: center; mso-hide: all;\">\n                                            👁 Potvrdit věcnou správnost\n                                        </a>\n                                        <!--<![endif]-->\n                                    </td>\n                                </tr>\n                            </table>\n                            \n                            <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse; margin-top: 30px; border-top: 1px solid #bfdbfe;\">\n                                <tr>\n                                    <td style=\"padding-top: 20px;\">\n                                        <p style=\"margin: 0; font-size: 14px; line-height: 1.6; color: #6b7280; font-family: Arial, sans-serif;\">\n                                            <p style=\"margin: 0; font-size: 14px; line-height: 1.6; color: #6b7280; font-family: Arial, sans-serif;\">Tento e-mail byl automaticky vygenerován systémem EEO v2.<br>Prosím zkontrolujte dodané zboží/služby a potvrďte věcnou správnost.</p>\n                                    </td>\n                                </tr>\n                            </table>\n                        </td>\n                    </tr>\n                    \n                    <!-- Footer -->\n                    <tr>\n                        <td style=\"background-color: #eff6ff; padding: 20px 30px; text-align: center; border-top: 1px solid #bfdbfe;\">\n                            <p style=\"margin: 0; font-size: 12px; color: #9ca3af; font-family: Arial, sans-serif;\">\n                                &copy; 2025 EEO V2 | Elektronická Evidence Objednávek\n                            </p>\n                        </td>\n                    </tr>\n                </table>\n            </td>\n        </tr>\n    </table>\n</body>\n</html>\n\n',1,'⚠️ Reklamace objednávky','Objednávka č. {order_number} byla zamítnuta při věcné kontrole - nutná reklamace','high',1,'2025-11-02 00:28:31','2025-12-22 01:01:47'),
(95,'system_maintenance','Plánovaná údržba systému','Plánovaná údržba systému - {maintenance_date}','Dobrý den,\n\ninformujeme Vás o plánované údržbě systému Evidence smluv:\n\nDatum: {maintenance_date}\nČas: {maintenance_start} - {maintenance_end}\nDůvod: {maintenance_reason}\n\nV tomto čase nebude systém dostupný. Děkujeme za pochopení.\n\nS pozdravem,\nTým Evidence smluv',1,'Plánovaná údržba: {maintenance_date}','Systém bude dne {maintenance_date} od {maintenance_start} do {maintenance_end} nedostupný z důvodu údržby','high',1,'2025-11-02 00:29:13','2025-11-05 21:46:38'),
(111,'order_comment_new','Nový komentář k objednávce','Nový komentář - objednávka č. {order_number}','Dobrý den,\n\nbyl přidán nový komentář k objednávce:\n\nObjednávka: {order_number}\nPředmět: {order_subject}\nAutor komentáře: {comment_author_name}\nDatum: {comment_date}\n\nKomentář:\n\"{comment_text}\"\n\nDetail najdete v aplikaci Evidence smluv.\n\nS pozdravem,\nSystém Evidence smluv',0,'Nový komentář k objednávce {order_number}','{comment_author_name} přidal komentář k objednávce č. {order_number}','low',1,'2025-11-02 00:30:23','2025-11-05 21:46:38'),
(112,'welcome_new_user','Uvítací email - Nový uživatel EEO systému','Váš přístup do EEO systému správy objednávek','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <title>Vítejte v ERDMS</title>\r\n</head>\r\n<body style=\"margin:0;padding:0;background:#f4f4f4;font-family:Arial,sans-serif;\">\r\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#f4f4f4\">\r\n    <tr>\r\n      <td align=\"center\" style=\"padding:40px 20px;\">\r\n        <table width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"border:1px solid #e0e0e0;\">\r\n          <!-- Modrý header s logem (bez gradientu) -->\r\n          <tr>\r\n            <td bgcolor=\"#3b7dbe\" style=\"padding:30px;\">\r\n              <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n                <tr>\r\n                  <td width=\"120\" valign=\"middle\" style=\"padding-right:20px;\">\r\n                    <img src=\"data:image/png;base64,\" alt=\"Logo ZZS\" style=\"display:block;width:100px;height:auto;\">\r\n                  </td>\r\n                  <td valign=\"middle\">\r\n                    <p style=\"margin:0 0 5px 0;padding:4px 12px;border:2px solid #ffffff;border-radius:20px;display:inline-block;font-size:12px;color:#ffffff;text-align:center;\">\r\n                      Zdravotnická záchranná služba Středočeského kraje, p.o.\r\n                    </p>\r\n                    <h1 style=\"margin:10px 0 5px 0;font-size:32px;color:#ffffff;font-weight:bold;\">\r\n                      Vítejte v EEO v2\r\n                    </h1>\r\n                    <p style=\"margin:0;font-size:16px;color:#ffffff;\">\r\n                      Elektrornická Evidence Objednávek\r\n                    </p>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n            </td>\r\n          </tr>\r\n          \r\n          <!-- Hlavní obsah -->\r\n          <tr>\r\n            <td style=\"padding:30px;\">\r\n              <p style=\"color:#222;font-size:16px;line-height:1.6;margin:0 0 20px 0;\">\r\n                Dobrý den,\r\n              </p>\r\n              \r\n              <p style=\"color:#222;font-size:16px;line-height:1.6;margin:0 0 20px 0;\">\r\n                s potěšením Vám oznamujeme, že Vám byl založen přístup k našemu novému <strong>EEO - Systému správy a workflow objednávek</strong>.\r\n              </p>\r\n              \r\n              <!-- Přihlašovací údaje -->\r\n              <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:20px 0;background:#f8f8f8;padding:15px;border-left:4px solid #3b7dbe;\">\r\n                <tr>\r\n                  <td>\r\n                    <p style=\"margin:0 0 10px 0;font-size:15px;color:#222;\">\r\n                      🔑 <strong>Tvoje přihlašovací údaje:</strong> {uzivatelske_jmeno} \r\n                    </p>\r\n                    <p style=\"margin:0 0 10px 0;font-size:15px;color:#222;\">\r\n                      🔑 <strong>Heslo [dočasné heslo]:</strong> {docasne_heslo}\r\n                    </p>\r\n                    <p style=\"margin:0;font-size:15px;color:#222;\">\r\n                      🌐 <strong>Odkaz na aplikaci:</strong> <a href=\"{prihlasovaci_url}\" style=\"color:#3b7dbe;text-decoration:underline;\">{prihlasovaci_url}</a>\r\n                    </p>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n              \r\n              <!-- Jak začít -->\r\n              <p style=\"color:#222;font-size:16px;margin:20px 0 10px 0;\">\r\n                ✅ <strong>Jak začít</strong>\r\n              </p>\r\n              \r\n              <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:0 0 20px 0;\">\r\n                <tr>\r\n                  <td style=\"padding:5px 0;font-size:15px;color:#222;line-height:1.6;\">\r\n                    1. Otevři aplikaci na <a href=\"{prihlasovaci_url}\" style=\"color:#3b7dbe;text-decoration:underline;\">{prihlasovaci_url}</a>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding:5px 0;font-size:15px;color:#222;line-height:1.6;\">\r\n                    2. Přihlaš se pomocí výše uvedených údajů\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding:5px 0;font-size:15px;color:#222;line-height:1.6;\">\r\n                    3. Při prvním přihlášení tě systém vyzve k zadání <strong>nové hesla</strong> 🔒\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding:5px 0;font-size:15px;color:#222;line-height:1.6;\">\r\n                    4. Přečti si <strong>Nápovědu</strong> a začni pracovat\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n              \r\n              <!-- Nápověda -->\r\n              <p style=\"color:#222;font-size:16px;line-height:1.6;margin:20px 0;\">\r\n                ❓ Pokud potřebujete pomoc, podívej se do <strong>Nápovědy</strong> v aplikaci nebo nás kontaktujte\r\n              </p>\r\n              \r\n              <!-- Kontakty -->\r\n              <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:20px 0;width:100%;border:1px solid #e0e0e0;background:#f9f9f9;\">\r\n                <tr>\r\n                  <td style=\"padding:15px;\">\r\n                    <p style=\"margin:0 0 15px 0;font-size:15px;color:#3b7dbe;font-weight:bold;\">\r\n                      📞 Kontakty a podpora\r\n                    </p>\r\n                    \r\n                    <table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:100%;\">\r\n                      <tr>\r\n                        <td style=\"padding:8px 0;font-size:14px;color:#222;\">\r\n                          <strong>IT hotline – nonstop</strong><br>\r\n                          Technická podpora 24/7\r\n                        </td>\r\n                        <td align=\"right\" style=\"padding:8px 0;font-size:14px;color:#3b7dbe;\">\r\n                          ☎ 731 137 100<br>\r\n                          ✉ helpdesk@zachranka.cz\r\n                        </td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td colspan=\"2\" style=\"padding:5px 0;border-top:1px solid #e0e0e0;\"></td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"padding:8px 0;font-size:14px;color:#222;\">\r\n                          <strong>Robert Holovský</strong><br>\r\n                          IT a programátor\r\n                        </td>\r\n                        <td align=\"right\" style=\"padding:8px 0;font-size:14px;color:#3b7dbe;\">\r\n                          ☎ 731 137 077<br>\r\n                          ✉ robert.holovsky@zachranka.cz\r\n                        </td>\r\n                      </tr>\r\n                    </table>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n              \r\n              <p style=\"color:#888;font-size:13px;line-height:1.5;margin:30px 0 0 0;\">\r\n                S pozdravem,<br>\r\n                <strong>Tým ERDMS</strong>\r\n              </p>\r\n            </td>\r\n          </tr>\r\n        </table>\r\n        \r\n        <!-- Footer -->\r\n        <p style=\"color:#aaa;font-size:12px;margin:20px 0 0 0;text-align:center;\">\r\n          &copy; {YEAR} Zdravotnická záchranná služba Středočeského kraje, příspěvková organizace\r\n        </p>\r\n      </td>\r\n    </tr>\r\n  </table>\r\n</body>\r\n</html>',1,'Nový přístup do EEO systému','Byl Vám založen přístup do EEO systému správy objednávek.','normal',1,'2025-12-28 20:46:08','2025-12-28 20:46:08'),
(113,'invoice_submitted','Faktura předána ke kontrole','✉️ Faktura č. {{invoice_number}} předána ke kontrole','<h2>Faktura předána ke kontrole</h2><p>Byla vám předána faktura k ověření a kontrole.</p><p><strong>Číslo faktury:</strong> {{invoice_number}}<br><strong>Dodavatel:</strong> {{supplier_name}}<br><strong>Částka:</strong> {{amount}} Kč<br><strong>Objednávka:</strong> {{order_number}}</p><p>Prosím zkontrolujte věcnou správnost a potvrďte.</p>',1,'📝 Faktura {{invoice_number}} předána','Faktura č. {{invoice_number}} od {{supplier_name}} byla předána ke kontrole. Částka: {{amount}} Kč','normal',1,'2025-12-31 02:38:49',NULL),
(114,'invoice_returned','Faktura vrácena k doplnění','⚠️ Faktura č. {{invoice_number}} vrácena k doplnění','<h2>Faktura vrácena</h2><p>Faktura byla vrácena k doplnění nebo opravě.</p><p><strong>Číslo faktury:</strong> {{invoice_number}}<br><strong>Dodavatel:</strong> {{supplier_name}}<br><strong>Důvod vrácení:</strong> {{return_reason}}</p><p>Prosím doplňte požadované údaje a předejte fakturu znovu.</p>',1,'⚠️ Faktura {{invoice_number}} vrácena','Faktura č. {{invoice_number}} vrácena k doplnění. Důvod: {{return_reason}}','normal',1,'2025-12-31 02:38:49',NULL),
(115,'invoice_material_check_requested','Věcná správnost faktury vyžadována','🔍 Vyžadována kontrola věcné správnosti faktury {{invoice_number}}','<h2>Vyžadována kontrola věcné správnosti</h2><p>Je třeba provést kontrolu věcné správnosti faktury.</p><p><strong>Číslo faktury:</strong> {{invoice_number}}<br><strong>Dodavatel:</strong> {{supplier_name}}<br><strong>Částka:</strong> {{amount}} Kč</p><p>Prosím ověřte, zda faktura odpovídá objednanému zboží/službám.</p>',1,'🔍 Kontrola faktury {{invoice_number}}','Vyžadována kontrola věcné správnosti faktury č. {{invoice_number}} ({{amount}} Kč)','normal',1,'2025-12-31 02:38:49',NULL),
(116,'invoice_updated','Faktura aktualizována','📝 Faktura č. {{invoice_number}} byla aktualizována','<h2>Faktura aktualizována</h2><p>V faktuře byly provedeny změny.</p><p><strong>Číslo faktury:</strong> {{invoice_number}}<br><strong>Aktualizoval:</strong> {{updated_by}}<br><strong>Datum změny:</strong> {{updated_at}}</p>',0,'📝 Faktura {{invoice_number}} aktualizována','Faktura č. {{invoice_number}} byla aktualizována uživatelem {{updated_by}}','normal',1,'2025-12-31 02:38:49',NULL),
(117,'invoice_material_check_approved','Věcná správnost faktury potvrzena','✅ Věcná správnost faktury {{invoice_number}} potvrzena','<h2>Věcná správnost potvrzena</h2><p>Věcná správnost faktury byla ověřena a potvrzena.</p><p><strong>Číslo faktury:</strong> {{invoice_number}}<br><strong>Dodavatel:</strong> {{supplier_name}}<br><strong>Částka:</strong> {{amount}} Kč<br><strong>Potvrdil:</strong> {{approved_by}}</p><p>Faktura může pokračovat ke zpracování.</p>',1,'✅ Faktura {{invoice_number}} ověřena','Věcná správnost faktury č. {{invoice_number}} byla potvrzena','normal',1,'2025-12-31 02:38:49',NULL),
(118,'invoice_registry_published','Faktura uveřejněna v registru','📢 Faktura č. {{invoice_number}} uveřejněna v registru','<h2>Faktura uveřejněna v registru</h2><p>Faktura byla úspěšně uveřejněna v registru smluv.</p><p><strong>Číslo faktury:</strong> {{invoice_number}}<br><strong>Dodavatel:</strong> {{supplier_name}}<br><strong>Datum uveřejnění:</strong> {{published_at}}</p>',0,'📢 Faktura {{invoice_number}} v registru','Faktura č. {{invoice_number}} byla uveřejněna v registru smluv','normal',1,'2025-12-31 02:38:49',NULL),
(119,'cashbook_month_closed','Pokladna uzavřena za měsíc','📅 Pokladna {{cashbook_name}} uzavřena za {{month_year}}','<h2>Pokladna uzavřena</h2><p>Pokladna byla uzavřena za ukončený měsíc.</p><p><strong>Pokladna:</strong> {{cashbook_name}}<br><strong>Období:</strong> {{month_year}}<br><strong>Uzavřel:</strong> {{closed_by}}<br><strong>Konečný zůstatek:</strong> {{final_balance}} Kč</p><p>Prosím ověřte správnost údajů před finálním uzamčením.</p>',1,'📅 Pokladna {{cashbook_name}} uzavřena','Pokladna {{cashbook_name}} uzavřena za {{month_year}}. Zůstatek: {{final_balance}} Kč','normal',1,'2025-12-31 02:38:49',NULL),
(120,'cashbook_month_locked','Pokladna uzamčena za měsíc','🔒 Pokladna {{cashbook_name}} UZAMČENA za {{month_year}}','<h2>⚠️ Pokladna finálně uzamčena</h2><p><strong>POZOR:</strong> Pokladna byla finálně uzamčena. Nelze provádět žádné změny!</p><p><strong>Pokladna:</strong> {{cashbook_name}}<br><strong>Období:</strong> {{month_year}}<br><strong>Uzamkl:</strong> {{locked_by}}<br><strong>Finální zůstatek:</strong> {{final_balance}} Kč</p><p>Data jsou nyní archivována a nelze je měnit.</p>',1,'🔒 Pokladna {{cashbook_name}} UZAMČENA','⚠️ Pokladna {{cashbook_name}} finálně uzamčena za {{month_year}}. Nelze měnit!','urgent',1,'2025-12-31 02:38:49',NULL);
INSERT INTO `25_notifikace_typy_udalosti` VALUES
(1,'ORDER_PENDING_APPROVAL','Objednávka odeslána ke schválení','orders','Objednatel odeslal objednávku ke schválení → notifikace příkazci/schvalovateli (trigger: ODESLANA_KE_SCHVALENI)','EXCEPTIONAL','[\"EXCEPTIONAL\",\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09','2025-12-16 21:50:03'),
(2,'ORDER_APPROVED','Objednávka schválena','orders','Příkazce schválil → notifikace objednateli, že může pokračovat','NORMAL','[\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(3,'ORDER_REJECTED','Objednávka zamítnuta','orders','Příkazce zamítl → proces končí','EXCEPTIONAL','[\"EXCEPTIONAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(4,'ORDER_AWAITING_CHANGES','Objednávka vrácena k doplnění','orders','Příkazce vrátil → objednatel doplní a znovu odešle','NORMAL','[\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(5,'ORDER_SENT_TO_SUPPLIER','Objednávka odeslána dodavateli','orders','Objednatel odeslal dodavateli → notifikace nákupčímu a příkazci','NORMAL','[\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(6,'ORDER_REGISTRY_APPROVAL_REQUESTED','Žádost o schválení v registru','orders','Příkazce žádá o registr → notifikace registru (role/hierarchie)','EXCEPTIONAL','[\"EXCEPTIONAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(7,'ORDER_INVOICE_ADDED','Faktura doplněna','orders','Registr doplnil fakturu → objednatel musí provést věcnou kontrolu','NORMAL','[\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(8,'ORDER_VERIFICATION_PENDING','Věcná kontrola provedena','orders','Objednatel provedl kontrolu → registr může dokončit','NORMAL','[\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(9,'ORDER_COMPLETED','Objednávka dokončena','orders','Registr dokončil → notifikace všem zúčastněným','NORMAL','[\"INFO\"]','[\"email\",\"inapp\"]','orders',1,'2025-12-16 18:31:09',NULL),
(10,'INVOICE_CREATED','Faktura vytvořena','invoices','Nová faktura byla vytvořena v systému','NORMAL','[\"APPROVAL\",\"INFO\"]','[\"email\",\"inapp\"]','invoices',1,'2025-12-16 18:31:09',NULL),
(11,'INVOICE_DUE_SOON','Faktura brzy po splatnosti','invoices','Faktura se blíží ke dni splatnosti','EXCEPTIONAL','[\"EXCEPTIONAL\",\"INFO\"]','[\"email\",\"inapp\",\"sms\"]','invoices',1,'2025-12-16 18:31:09',NULL),
(12,'INVOICE_OVERDUE','Faktura po splatnosti','invoices','Faktura je po splatnosti','EXCEPTIONAL','[\"EXCEPTIONAL\"]','[\"email\",\"inapp\",\"sms\"]','invoices',1,'2025-12-16 18:31:09',NULL),
(13,'CONTRACT_EXPIRING','Smlouva brzy vyprší','contracts','Smlouva se blíží ke konci platnosti','EXCEPTIONAL','[\"EXCEPTIONAL\",\"INFO\"]','[\"email\",\"inapp\"]','contracts',1,'2025-12-16 18:31:09',NULL),
(14,'CASHBOOK_LOW_BALANCE','Nízký zůstatek v pokladně','cashbook','Zůstatek v pokladně je pod minimální hranicí','EXCEPTIONAL','[\"EXCEPTIONAL\",\"INFO\"]','[\"email\",\"inapp\"]','cashbook',1,'2025-12-16 18:31:09',NULL),
(15,'INVOICE_SUBMITTED','Faktura předána','invoices','Událost nastane při předání faktury ke kontrole nebo schválení','NORMAL','[\"GARANT\",\"THP_PES\"]','[\"app\",\"email\"]','invoices',1,'2025-12-31 02:38:49',NULL),
(16,'INVOICE_RETURNED','Faktura vrácena','invoices','Událost nastane při vrácení faktury k doplnění nebo opravě','NORMAL','[\"CREATOR\",\"GARANT\"]','[\"app\",\"email\"]','invoices',1,'2025-12-31 02:38:49',NULL),
(17,'INVOICE_MATERIAL_CHECK_REQUESTED','Věcná správnost vyžadována','invoices','Událost nastane když je třeba provést kontrolu věcné správnosti faktury','NORMAL','[\"GARANT\",\"THP_PES\"]','[\"app\",\"email\"]','invoices',1,'2025-12-31 02:38:49',NULL),
(18,'INVOICE_UPDATED','Faktura aktualizována','invoices','Událost nastane při jakékoli aktualizaci údajů faktury','NORMAL','[\"GARANT\",\"THP_PES\",\"CREATOR\"]','[\"app\"]','invoices',1,'2025-12-31 02:38:49',NULL),
(19,'INVOICE_MATERIAL_CHECK_APPROVED','Věcná správnost faktury potvrzena','invoices','Událost nastane po potvrzení věcné správnosti faktury','NORMAL','[\"CREATOR\",\"GARANT\",\"ACCOUNTANT\"]','[\"app\",\"email\"]','invoices',1,'2025-12-31 02:38:49',NULL),
(20,'INVOICE_REGISTRY_PUBLISHED','Faktura uveřejněna v registru','invoices','Událost nastane po uveřejnění faktury v registru smluv','NORMAL','[\"CREATOR\",\"GARANT\"]','[\"app\"]','invoices',1,'2025-12-31 02:38:49',NULL),
(21,'CASHBOOK_MONTH_CLOSED','Pokladna uzavřena za měsíc','cashbook','Událost nastane po uzavření pokladny za ukončený měsíc','NORMAL','[\"ACCOUNTANT\",\"MANAGER\"]','[\"app\",\"email\"]','cashbook',1,'2025-12-31 02:38:49',NULL),
(22,'CASHBOOK_MONTH_LOCKED','Pokladna uzamčena za měsíc','cashbook','Událost nastane po finálním uzamčení pokladny za měsíc (nelze měnit)','URGENT','[\"ACCOUNTANT\",\"MANAGER\"]','[\"app\",\"email\"]','cashbook',1,'2025-12-31 02:38:49',NULL);
